{
  "name": "@devcxl/opencode-cabbage",
  "version": "2.0.0",
  "description": "OpenCode 全流程开发插件 — 需求→设计→任务→编码→测试→审查→自动合并，支持自动编排与并行 Subagent",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/devcxl/opencode-cabbage.git"
  },
  "homepage": "https://github.com/devcxl/opencode-cabbage",
  "bugs": {
    "url": "https://github.com/devcxl/opencode-cabbage/issues"
  },
  "keywords": [
    "codex",
    "codex-plugin",
    "development-workflow",
    "orchestration",
    "tdd",
    "opencode",
    "opencode-plugin"
  ],
  "type": "module",
  "engines": {
    "node": ">=24"
  },
  "main": "./dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js"
    },
    "./server": {
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist",
    "assets",
    "vendor",
    "README.md",
    ".codex-plugin",
    "codex-skills",
    "hooks"
  ],
  "publishConfig": {
    "registry": "https://registry.npmjs.org/",
    "access": "public"
  },
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.json",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "vitest run",
    "prompt-lint": "vitest run test/plugin/prompt-lint.test.ts",
    "test:pack": "npm run build && pack_out=$(npm pack --dry-run 2>&1); echo \"$pack_out\" | grep -q 'dist/kernel/' || { echo 'FAIL: tarball 缺少 dist/kernel/'; exit 1; }; echo \"$pack_out\" | grep -q 'dist/flowrun/' && { echo 'FAIL: tarball 含过期 flowrun/ 残留'; exit 1; }; for f in '.codex-plugin/plugin.json' 'codex-skills/flow-setup/SKILL.md' 'codex-skills/agent-dev-lifecycle/SKILL.md' 'hooks/hooks.json' 'dist/hooks/session-start.js' 'vendor/cabbage/MANIFEST.json' 'vendor/cabbage/cabbage_cli/cli.py' 'vendor/cabbage/cabbage_cli/assets/workflows/change.yaml'; do echo \"$pack_out\" | grep -q \"$f\" || { echo \"FAIL: tarball 缺少 $f\"; exit 1; }; done; echo 'PASS: tarball 含 dist/kernel/ + 内置 cabbage 引擎（vendor） + Codex 插件文件，无 flowrun/ 残留'",
    "docs:dev": "vitepress dev docs",
    "docs:build": "vitepress build docs",
    "docs:preview": "vitepress preview docs"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.28",
    "yaml": "^2.8.3"
  },
  "devDependencies": {
    "@types/node": "^24.6.0",
    "mermaid": "^11.16.0",
    "typescript": "^5.9.3",
    "vitepress": "^1.6.4",
    "vitepress-plugin-mermaid": "^2.0.17",
    "vitest": "^3.2.4"
  }
}

{
  "name": "docs",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vitepress dev .",
    "build": "vitepress build .",
    "preview": "vitepress preview ."
  },
  "devDependencies": {
    "mermaid": "^11.4.1",
    "vitepress": "^1.6.4",
    "vitepress-plugin-mermaid": "^2.0.17",
    "vue": "^3.5.13"
  }
}
